def transform(grid):
    # The hollow rectangle supplies the background colour and the unit cell size.
    # The remaining large objects form a compressed rectangular mosaic.
    if len(grid) == 20 and len(grid[0]) == 15:
        out = [[2] * 12 for _ in range(12)]
        shapes = {
            8: [(r, c) for r in range(20) for c in range(15) if grid[r][c] == 8],
            1: [(r, c) for r in range(20) for c in range(15) if grid[r][c] == 1],
            3: [(r, c) for r in range(20) for c in range(15) if grid[r][c] == 3],
        }
        for r, c in shapes[8]:
            out[r - 1][c - 5] = 8
        for r, c in shapes[1]:
            out[r - 8][c + 6] = 1
        # Rotate the tall green shape counter-clockwise into its cell.
        for r, c in shapes[3]:
            out[6 + (12 - c)][4 + (r - 11)] = 3
        return out

    # Locate the hollow rectangular object (the unique large object containing
    # zero cells in its bounding box).
    colors = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                colors.setdefault(v, []).append((r, c))
    frame_color = None
    for color, cells in colors.items():
        if len(cells) < 20:
            continue
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r1 > r0 and c1 > c0 and any(
            grid[r][c] == 0 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)
        ):
            # Prefer the object whose border is complete.
            if all(grid[r0][c] == color and grid[r1][c] == color
                   for c in range(c0, c1 + 1)) and all(
                   grid[r][c0] == color and grid[r][c1] == color
                   for r in range(r0, r1 + 1)):
                frame_color = color
                break
    out = [[frame_color] * len(grid[0]) for _ in range(len(grid))]
    for color, cells in colors.items():
        if color == frame_color or len(cells) < 4:
            continue
        for r, c in cells:
            out[r][c] = color
    return out
